#!/usr/bin/env python3
from pathlib import Path
import base64, gzip, sys

if len(sys.argv) != 2: raise SystemExit('usage: 0141-volumetric-boundary.py <source-root>')
root = Path(sys.argv[1]).resolve()

FILES = {'src/main/java/dev/futurae/veilbound/client/render/VeilBoundaryRenderer.java': '', 'src/main/resources/assets/veilbound/shaders/core/veil_boundary.fsh': '', 'src/main/resources/assets/veilbound/shaders/core/veil_boundary.vsh': ''}

for rel, encoded in FILES.items():
    p = root / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(gzip.decompress(base64.b64decode(encoded)))

print('Applied 0.1.41 seam-free world-position volumetric Veil rendering')